export const PROJECT_KEY_MAX_LENGTH = 4;

/**
 * Makes a project key unique within `taken` the way `uniqueSlug` does for
 * addresses: by appending `2`, `3`, … and trimming the base so the key never
 * exceeds `PROJECT_KEY_MAX_LENGTH` characters.
 */
export function uniqueProjectKey(input: string, taken: Iterable<string>): string {
  const base =
    input.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, PROJECT_KEY_MAX_LENGTH) ||
    "TASK";
  const used = new Set(Array.from(taken, (key) => key.toUpperCase()));
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 10_000; suffix += 1) {
    const tail = String(suffix);
    const head = base.slice(0, Math.max(0, PROJECT_KEY_MAX_LENGTH - tail.length));
    const candidate = `${head}${tail}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique key suffixes");
}
